const input = $input.first().json ?? {};
const fail = (responseStatus, errorCode) => [{ json: { valid: false, responseStatus, errorCode } }];
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isId = (value) => typeof value === 'string' && value.length >= 1 && value.length <= 64;
const cleanText = (value, max) => {
  if (typeof value !== 'string') return null;
  const clean = value.trim().replace(/[\u0000-\u001f\u007f]/g, ' ');
  return clean.length >= 1 && clean.length <= max ? clean : null;
};
const utf8Length = (value) => {
  let bytes = 0;
  for (const character of value) {
    const point = character.codePointAt(0);
    bytes += point <= 0x7f ? 1 : point <= 0x7ff ? 2 : point <= 0xffff ? 3 : 4;
  }
  return bytes;
};
const rawHeaders = isObject(input.headers) ? input.headers : {};
const headers = {};
for (const [name, value] of Object.entries(rawHeaders)) {
  headers[name.toLowerCase()] = Array.isArray(value) ? String(value[0] ?? '') : String(value ?? '');
}
const supplied = headers['x-vantix-signature']?.trim().toLowerCase() ?? '';
const calculated = String(input.computedSignature ?? '').toLowerCase();
if (!/^sha256=[a-f0-9]{64}$/.test(supplied) || !/^[a-f0-9]{64}$/.test(calculated)) {
  return fail(401, 'invalid_signature');
}
let signatureDifference = 0;
for (let index = 0; index < 64; index += 1) {
  signatureDifference |= supplied.charCodeAt(index + 7) ^ calculated.charCodeAt(index);
}
if (signatureDifference !== 0) return fail(401, 'invalid_signature');
const body = input.body;
if (!isObject(body)) return fail(400, 'invalid_json');
let payloadJson;
try {
  payloadJson = JSON.stringify(body.payload);
} catch {
  return fail(400, 'invalid_payload');
}
if (typeof payloadJson !== 'string' || utf8Length(payloadJson) > 32768) {
  return fail(413, 'payload_too_large');
}
if (!Number.isSafeInteger(body.timestamp) || body.timestamp <= 0) return fail(400, 'invalid_timestamp');
if (headers['x-vantix-timestamp'] !== String(body.timestamp)) return fail(401, 'timestamp_mismatch');
if (Math.abs(Date.now() - body.timestamp) > 300000) return fail(401, 'stale_timestamp');
if (!isId(body.eventId) || !isId(body.organizationId) || !isId(body.runId)) return fail(400, 'invalid_identity');
if (headers['x-vantix-event-id'] !== body.eventId) return fail(400, 'event_id_mismatch');
if (body.schemaVersion !== 1 || headers['x-vantix-schema-version'] !== '1') return fail(422, 'unsupported_schema');
if (typeof body.idempotencyKey !== 'string' || body.idempotencyKey.length < 1 || body.idempotencyKey.length > 200) {
  return fail(400, 'invalid_idempotency_key');
}
if (!isObject(body.payload)) return fail(400, 'invalid_payload');
const eventBase = {
  eventId: body.eventId,
  organizationId: body.organizationId,
  runId: body.runId,
  type: body.type,
  timestamp: body.timestamp,
  schemaVersion: 1,
  idempotencyKey: body.idempotencyKey,
};
let safePayload;
if (body.type === 'conversation.handoff_requested') {
  const payload = body.payload;
  if (payload.eventId !== body.eventId || payload.organizationId !== body.organizationId || !isId(payload.conversationId)) {
    return fail(400, 'invalid_handoff_identity');
  }
  const businessName = cleanText(payload.businessName, 100);
  const customerName = cleanText(payload.customerName, 100);
  const conversationUrl = cleanText(payload.conversationUrl, 1000);
  const requestedAt = cleanText(payload.requestedAt, 40);
  if (!businessName || !customerName || !conversationUrl || !/^https?:\/\//i.test(conversationUrl) || !requestedAt || !Number.isFinite(Date.parse(requestedAt))) {
    return fail(400, 'invalid_handoff_payload');
  }
  const normalizeRecipient = (recipient) => {
    if (!isObject(recipient) || !isId(recipient.userId)) return null;
    const name = cleanText(recipient.name, 100);
    const email = cleanText(recipient.email, 254);
    if (!name || !email || !email.includes('@') || !['OWNER', 'ADMIN', 'AGENT'].includes(recipient.role)) return null;
    return { userId: recipient.userId, name, email, role: recipient.role };
  };
  if (!Array.isArray(payload.recipients) || payload.recipients.length < 1 || payload.recipients.length > 50) {
    return fail(400, 'invalid_handoff_recipients');
  }
  const recipientMap = new Map();
  for (const rawRecipient of payload.recipients) {
    const recipient = normalizeRecipient(rawRecipient);
    if (!recipient) return fail(400, 'invalid_handoff_recipients');
    recipientMap.set(recipient.userId, recipient);
  }
  let assignedAgent = null;
  if (payload.assignedAgent !== null && payload.assignedAgent !== undefined) {
    assignedAgent = normalizeRecipient(payload.assignedAgent);
    if (!assignedAgent) return fail(400, 'invalid_assigned_agent');
  }
  safePayload = {
    eventId: body.eventId,
    organizationId: body.organizationId,
    conversationId: payload.conversationId,
    businessName,
    customerName,
    conversationUrl,
    requestedAt: new Date(requestedAt).toISOString(),
    assignedAgent,
    recipients: [...recipientMap.values()],
  };
} else if (body.type === 'conversation.followup_due') {
  const payload = body.payload;
  if (payload.eventId !== body.eventId || payload.organizationId !== body.organizationId || !isId(payload.conversationId)) {
    return fail(400, 'invalid_followup_identity');
  }
  const scheduledFor = cleanText(payload.scheduledFor, 40);
  if (!scheduledFor || !Number.isFinite(Date.parse(scheduledFor)) || !Number.isInteger(payload.followUpNumber) || payload.followUpNumber < 1 || payload.followUpNumber > 3 || payload.reason !== 'outbound_message_unanswered') {
    return fail(400, 'invalid_followup_payload');
  }
  safePayload = {
    eventId: body.eventId,
    organizationId: body.organizationId,
    conversationId: payload.conversationId,
    scheduledFor: new Date(scheduledFor).toISOString(),
    followUpNumber: payload.followUpNumber,
    reason: 'outbound_message_unanswered',
  };
} else if (body.type === 'automation.test') {
  if (!['connection-test', 'manual-test'].includes(body.payload.source)) return fail(400, 'invalid_test_payload');
  safePayload = { source: body.payload.source };
} else {
  return fail(422, 'unsupported_event_type');
}
return [{ json: { valid: true, responseStatus: 202, event: { ...eventBase, payload: safePayload } } }];

const event = $input.first().json.event;
const callbackTimestamp = Date.now();
const callbackBody = JSON.stringify({
  eventId: event.eventId,
  organizationId: event.organizationId,
  runId: event.runId,
  timestamp: callbackTimestamp,
  status: 'succeeded',
  externalExecutionId: String($execution.id),
  responseMeta: { workflow: 'vantix-event-router', eventType: 'automation.test' },
});
return [{ json: { callbackBody, callbackTimestamp: String(callbackTimestamp) } }];
